command:
$ErrorActionPreference = 'Stop'
$branch = 'issue-484-lane-separation-scoring'
$expectedHead = '208b0f9306767f2ff6a8153801e37fed375a56b2'
$sourcePath = 'project_sources/gemini/tools/lib/gemini_behavioral_replay_scoring.py'
$validatorPath = 'project_sources/gemini/tools/validate_gemini_lane_separation_scoring.py'
function Invoke-Git([string[]]$GitArgs) {
  Write-Host "git $($GitArgs -join ' ')"
  $output = & git @GitArgs
  $code = $LASTEXITCODE
  if ($output) { $output | Out-Host }
  if ($code -ne 0) { throw "git failed with exit $code`: git $($GitArgs -join ' ')" }
}
Invoke-Git @('fetch', '--no-tags', 'origin', "refs/heads/$branch`:refs/remotes/origin/$branch")
$remoteHead = (& git rev-parse "refs/remotes/origin/$branch").Trim()
if ($LASTEXITCODE -ne 0) { throw 'Unable to read remote branch head.' }
Write-Host "Remote PR head: $remoteHead"
if ($remoteHead -ne $expectedHead) { throw "PR head drifted: expected $expectedHead got $remoteHead" }
$worktree = Join-Path $env:RUNNER_TEMP 'issue484_pr501_exact_head_208b'
if (Test-Path -LiteralPath $worktree) { Remove-Item -LiteralPath $worktree -Recurse -Force }
Invoke-Git @('worktree', 'prune')
Invoke-Git @('worktree', 'add', '--detach', $worktree, $remoteHead)
try {
  Push-Location $worktree
  $env:PYTHONDONTWRITEBYTECODE = '1'
  foreach ($name in @('OPENROUTER_API_KEY','OPENAI_API_KEY','GEMINI_API_KEY','GOOGLE_API_KEY','DCOIR_GEMINI_API','DCOIR_OPENAI_API_KEY','DCOIR_OPENAI_PROJECT_ID')) { Remove-Item "Env:$name" -ErrorAction SilentlyContinue }
  python -m py_compile $sourcePath $validatorPath
  if ($LASTEXITCODE -ne 0) { throw 'py_compile failed.' }
  python $validatorPath
  if ($LASTEXITCODE -ne 0) { throw 'focused lane-separation regression failed.' }
  $outDir = Join-Path $env:RUNNER_TEMP 'issue484-full-replay-validation-exact-head-208b'
  if (Test-Path -LiteralPath $outDir) { Remove-Item -LiteralPath $outDir -Recurse -Force }
  New-Item -ItemType Directory -Path $outDir -Force | Out-Null
  python project_sources/gemini/tools/run_gemini_behavioral_replay_validation_suite.py --fixtures-root project_sources/gemini/fixtures/behavioral_replay --output-dir $outDir
  if ($LASTEXITCODE -ne 0) { throw 'full deterministic Gemini behavioral replay validation failed.' }
  $status = @(& git status --porcelain)
  if ($status.Count -ne 0) { throw "Detached validation worktree is not clean: $($status -join '; ')" }
  $validated = (& git rev-parse HEAD).Trim()
  if ($validated -ne $expectedHead) { throw "Validated wrong head: $validated" }
  Write-Host "ISSUE484_POST_DCOIR_EXACT_HEAD_VALIDATION=PASS:$validated"
} finally {
  Pop-Location -ErrorAction SilentlyContinue
  & git worktree remove --force $worktree 2>$null
  & git worktree prune 2>$null
}
